//! Amortized (precompute-once) genus-2 index calculus and matched precomputed rho.
//!
//! The transfer `E1 -> J(C)` is a one-time cost and is not part of anything
//! here. This module measures what is left once it exists, in the order-`r`
//! subgroup of `J(C)(F_p)` generated by `G`:
//!
//! - [`ic_precompute`] / [`ic_descent`]: the factor-base logarithms are computed
//!   once from relations in `G` alone (a structured elimination for weight-2
//!   rows, see [`Dsu`]), then each target needs only a descent
//!   `T + [beta]G = sum eps_i g_i`;
//! - [`bl_precompute`] / [`bl_online`]: the matched control, Bernstein-Lange
//!   precomputed rho (a table of distinguished points of walks from known
//!   multiples of `G`), required by the N83 precomputed-rho study;
//! - [`certify_dlog`]: an independent double-and-add check `[k]G == T`.
//!
//! One counted unit is one Cantor addition or doubling. Linear-algebra work is
//! counted separately in modular operations over `Z/r` ([`LaCount`]) so a
//! caller can price it at 0, 0.1 and 1 GAE per operation.
//!
//! Factor-base elements may lie outside the order-`r` subgroup. With
//! `cof = #J / r` and `r` prime with `r^2 ∤ #J`, `cof` is a unit mod `r`, so
//! projecting every element by `[cof]` and taking logs to base `[cof]G` turns a
//! relation `R = sum eps_i g_i` (with `R` in the subgroup) into
//! `log R = sum eps_i L_i (mod r)`. The unknowns `L_i` are those projected
//! logs; nothing in the solve needs `cof` itself (tests use it to check).
//! Places with `y = 0` are 2-torsion and project to 0 (odd `r`).

use super::field::Fp;
use crate::cryptanalysis::genus2_fp::{Divisor, Genus2Curve};
use std::collections::HashMap;

// ── small helpers ───────────────────────────────────────────────────────────

/// xorshift64* generator, seeded through splitmix64.
#[derive(Clone, Debug)]
pub struct Rng64(u64);

impl Rng64 {
    pub fn new(seed: u64) -> Self {
        let mut z = seed.wrapping_add(0x9E37_79B9_7F4A_7C15);
        z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
        z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
        z ^= z >> 31;
        Rng64(z | 1)
    }
    pub fn next_u64(&mut self) -> u64 {
        let mut x = self.0;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.0 = x;
        x.wrapping_mul(0x2545_F491_4F6C_DD1D)
    }
    /// Uniform in `[0, n)` (modulo bias is negligible for `n << 2^64`).
    pub fn below(&mut self, n: u64) -> u64 {
        self.next_u64() % n
    }
}

fn mix64(mut z: u64) -> u64 {
    z = (z ^ (z >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    z = (z ^ (z >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    z ^ (z >> 31)
}

/// Key of a divisor class for hashing (the class itself is compared exactly).
fn dkey(d: &Divisor) -> u64 {
    let mut k = (d.degree() as u64).wrapping_add(0x9E37_79B9_7F4A_7C15);
    for c in d.u_coeffs().iter().chain(d.v_coeffs().iter()) {
        k = (k ^ *c).wrapping_mul(0xC2B2_AE3D_27D4_EB4F);
        k ^= k >> 29;
    }
    k
}

/// Cantor addition charged one unit unless an operand is the identity (a copy,
/// not a group operation; `measure.rs` and `rho_reference` count the same way).
fn cadd(c: &Genus2Curve, a: &Divisor, b: &Divisor, ops: &mut u64) -> Divisor {
    if !a.is_identity() && !b.is_identity() {
        *ops += 1;
    }
    c.add(a, b)
}

fn bits_of(r: u64) -> usize {
    (64 - r.leading_zeros()) as usize
}

fn addmod(a: u64, b: u64, r: u64) -> u64 {
    let s = a as u128 + b as u128;
    (s % r as u128) as u64
}

fn submod(a: u64, b: u64, r: u64) -> u64 {
    if a >= b {
        a - b
    } else {
        a + r - b
    }
}

fn negmod(a: u64, r: u64) -> u64 {
    if a == 0 {
        0
    } else {
        r - a
    }
}

// ── independent certificate ─────────────────────────────────────────────────

/// Independent check that `[k]G == T`, by a fresh LSB-first double-and-add that
/// shares no code with `measure::scalar_counted` or `Genus2Curve::mul`.
/// Returns `(holds, group_ops)`; the ops are what a caller who charges the
/// certificate to an arm adds.
pub fn certify_dlog(c: &Genus2Curve, g: &Divisor, t: &Divisor, k: u64) -> (bool, u64) {
    let mut ops = 0u64;
    let mut acc = Divisor::IDENTITY;
    let mut base = *g;
    let mut e = k;
    while e > 0 {
        if e & 1 == 1 {
            acc = cadd(c, &acc, &base, &mut ops);
        }
        e >>= 1;
        if e > 0 {
            base = cadd(c, &base, &base.clone(), &mut ops);
        }
    }
    (acc == *t, ops)
}

/// `[n]d` by LSB-first double-and-add, charged.
fn mul_counted(c: &Genus2Curve, d: &Divisor, n: u64, ops: &mut u64) -> Divisor {
    let mut acc = Divisor::IDENTITY;
    let mut base = *d;
    let mut e = n;
    while e > 0 {
        if e & 1 == 1 {
            acc = cadd(c, &acc, &base, ops);
        }
        e >>= 1;
        if e > 0 {
            base = cadd(c, &base, &base.clone(), ops);
        }
    }
    acc
}

// ── power table of G ────────────────────────────────────────────────────────

/// `[2^i]G` for `i < bits(r)`; a multiple `[a]G` then costs `popcount(a) - 1`
/// additions. The table's `bits - 1` doublings are counted once in `setup_ops`.
#[derive(Clone, Debug)]
pub struct PowTable {
    pub pow: Vec<Divisor>,
    pub setup_ops: u64,
}

impl PowTable {
    pub fn new(c: &Genus2Curve, g: &Divisor, bits: usize) -> Self {
        let mut ops = 0u64;
        let mut pow = vec![*g];
        for _ in 1..bits {
            let last = *pow.last().unwrap();
            pow.push(cadd(c, &last, &last, &mut ops));
        }
        PowTable {
            pow,
            setup_ops: ops,
        }
    }

    /// `base + [a]G`, charging the additions.
    pub fn add_mul(&self, c: &Genus2Curve, base: &Divisor, a: u64, ops: &mut u64) -> Divisor {
        let mut acc = *base;
        let mut e = a;
        let mut i = 0;
        while e > 0 {
            if e & 1 == 1 {
                acc = cadd(c, &acc, &self.pow[i], ops);
            }
            e >>= 1;
            i += 1;
        }
        acc
    }

    /// `[a]G`.
    pub fn mul(&self, c: &Genus2Curve, a: u64, ops: &mut u64) -> Divisor {
        self.add_mul(c, &Divisor::IDENTITY, a, ops)
    }
}

// ── factor base ─────────────────────────────────────────────────────────────

/// The full degree-1 factor base: every `x` with an affine point, with the
/// canonical `y0 = min(y, p - y)`. The place is the class `[(x, y0) - inf]`.
#[derive(Clone, Debug)]
pub struct Fb {
    pub p: u64,
    pub xs: Vec<u64>,
    pub y0: Vec<u64>,
    idx: Vec<u32>,
}

impl Fb {
    pub fn new(c: &Genus2Curve) -> Self {
        let p = c.p();
        let k = Fp::new(p).expect("prime field");
        let mut xs = vec![];
        let mut y0 = vec![];
        let mut idx = vec![u32::MAX; p as usize];
        for x in 0..p {
            if let Some(y) = k.sqrt(c.eval_f(x)) {
                idx[x as usize] = xs.len() as u32;
                xs.push(x);
                y0.push(y.min((p - y) % p));
            }
        }
        Fb { p, xs, y0, idx }
    }
    pub fn len(&self) -> usize {
        self.xs.len()
    }
    pub fn is_empty(&self) -> bool {
        self.xs.is_empty()
    }
    pub fn index(&self, x: u64) -> Option<usize> {
        match self.idx.get(x as usize) {
            Some(&i) if i != u32::MAX => Some(i as usize),
            _ => None,
        }
    }
}

/// Decompose a degree-2 reduced class into two distinct base places with signs
/// (`+1` when the root's `y` equals the canonical `y0`, else `-1`). `None` for
/// every other shape (degree != 2, irreducible or repeated `u`).
pub fn decompose(k: &Fp, fb: &Fb, d: &Divisor) -> Option<[(usize, i8); 2]> {
    if d.degree() != 2 {
        return None;
    }
    let p = k.p;
    let u = d.u_coeffs();
    let v = d.v_coeffs();
    let (c0, c1) = (u[0], u[1]);
    let disc = k.sub(k.mul(c1, c1), k.mul(4, c0));
    let s = k.sqrt(disc)?;
    let inv2 = k.inv(2);
    let r1 = k.mul(k.add(k.neg(c1), s), inv2);
    let r2 = k.mul(k.sub(k.neg(c1), s), inv2);
    if r1 == r2 {
        return None;
    }
    let mut out = [(0usize, 0i8); 2];
    for (slot, x) in [r1, r2].into_iter().enumerate() {
        let mut y = 0u64;
        for &cf in v.iter().rev() {
            y = k.add(k.mul(y, x), cf);
        }
        let i = fb.index(x)?;
        let y0 = y.min((p - y) % p);
        out[slot] = (i, if y == y0 { 1 } else { -1 });
    }
    Some(out)
}

// ── structured elimination for weight-2 relations ───────────────────────────

/// Linear-algebra work over `Z/r`, counted per modular operation.
#[derive(Clone, Copy, Debug, Default)]
pub struct LaCount {
    /// Modular multiplications (here: by `1/2` only).
    pub mulmods: u64,
    /// Every modular operation (additions, subtractions, negations,
    /// multiplications), the unit priced per operation in section 5a.
    pub total: u64,
}

/// Weighted union-find over `Z/r`: every unknown is `L_v = a_v + s_v * t_root`
/// with `s_v = +-1`. A relation `e1 L_i + e2 L_j = alpha` either merges two
/// components (no multiplication), checks consistency, or, closing a cycle
/// with `e1 s_i + e2 s_j = +-2`, fixes the component's root by one
/// multiplication with `1/2` (`r` odd). This is Gaussian elimination
/// specialised to rows of weight two; it is a fixed property of the relation
/// shape, not a tuning choice.
pub struct Dsu {
    r: u64,
    inv2: u64,
    parent: Vec<u32>,
    a: Vec<u64>,
    s: Vec<i8>,
    size: Vec<u32>,
    fixed: Vec<Option<u64>>,
    scratch: Vec<u32>,
    pub determined: usize,
    pub inconsistent: u64,
    pub la: LaCount,
}

impl Dsu {
    pub fn new(n: usize, r: u64) -> Self {
        Dsu {
            r,
            inv2: r.div_ceil(2), // (r + 1) / 2 for odd r
            parent: (0..n as u32).collect(),
            a: vec![0; n],
            s: vec![1; n],
            size: vec![1; n],
            fixed: vec![None; n],
            scratch: vec![],
            determined: 0,
            inconsistent: 0,
            la: LaCount::default(),
        }
    }

    fn op(&mut self) {
        self.la.total += 1;
    }

    /// Declare `L_v = value` outright (used for 2-torsion places, `L = 0`).
    pub fn fix(&mut self, v: usize, value: u64) {
        let root = self.find(v);
        if self.fixed[root].is_none() {
            let t = if root == v {
                value
            } else {
                // L_v = a_v + s_v t  =>  t = s_v (L - a_v)
                self.op();
                let d = submod(value, self.a[v], self.r);
                if self.s[v] == 1 {
                    d
                } else {
                    negmod(d, self.r)
                }
            };
            self.fixed[root] = Some(t);
            self.determined += self.size[root] as usize;
        }
    }

    /// Root of `v`, compressing the path (one addition per compressed node).
    fn find(&mut self, v: usize) -> usize {
        let mut x = v;
        let mut path = std::mem::take(&mut self.scratch);
        path.clear();
        while self.parent[x] as usize != x {
            path.push(x as u32);
            x = self.parent[x] as usize;
        }
        let root = x;
        for &n in path.iter().rev() {
            let n = n as usize;
            let p = self.parent[n] as usize;
            if p != root {
                // L_n = a_n + s_n (a_p + s_p t) = (a_n + s_n a_p) + s_n s_p t
                let ap = if self.s[n] == 1 {
                    self.a[p]
                } else {
                    negmod(self.a[p], self.r)
                };
                self.a[n] = addmod(self.a[n], ap, self.r);
                self.s[n] *= self.s[p];
                self.parent[n] = root as u32;
                self.la.total += 1;
            }
        }
        self.scratch = path;
        root
    }

    /// Add `e1 L_i + e2 L_j = alpha (mod r)`.
    pub fn relation(&mut self, i: usize, e1: i8, j: usize, e2: i8, alpha: u64) {
        let r = self.r;
        let ri = self.find(i);
        let rj = self.find(j);
        // coefficients of the roots' unknowns and the constant
        let ci = e1 * self.s[i];
        let cj = e2 * self.s[j];
        let ai = if e1 == 1 {
            self.a[i]
        } else {
            negmod(self.a[i], r)
        };
        let aj = if e2 == 1 {
            self.a[j]
        } else {
            negmod(self.a[j], r)
        };
        let k = submod(submod(alpha, ai, r), aj, r);
        self.la.total += 2;
        // c * x for c = +-1
        let sg = |c: i8, x: u64| if c == 1 { x } else { negmod(x, r) };
        if ri != rj {
            match (self.fixed[ri], self.fixed[rj]) {
                (Some(ti), Some(tj)) => {
                    let lhs = addmod(sg(ci, ti), sg(cj, tj), r);
                    self.la.total += 1;
                    if lhs != k {
                        self.inconsistent += 1;
                    }
                }
                (Some(ti), None) => {
                    // tj = cj (k - ci ti)
                    let tj = sg(cj, submod(k, sg(ci, ti), r));
                    self.la.total += 2;
                    self.fixed[rj] = Some(tj);
                    self.determined += self.size[rj] as usize;
                }
                (None, Some(tj)) => {
                    let ti = sg(ci, submod(k, sg(cj, tj), r));
                    self.la.total += 2;
                    self.fixed[ri] = Some(ti);
                    self.determined += self.size[ri] as usize;
                }
                (None, None) => {
                    // attach the smaller root under the larger one
                    let (child, parent, cc, cp) = if self.size[ri] >= self.size[rj] {
                        (rj, ri, cj, ci)
                    } else {
                        (ri, rj, ci, cj)
                    };
                    // cc t_child + cp t_parent = k  =>  t_child = cc k - cc cp t_parent
                    self.a[child] = sg(cc, k);
                    self.s[child] = -(cc * cp);
                    self.parent[child] = parent as u32;
                    self.size[parent] += self.size[child];
                    self.la.total += 1;
                }
            }
        } else {
            // cycle: (ci + cj) t = k
            let sum = ci + cj;
            if sum == 0 {
                self.la.total += 1;
                if k != 0 {
                    self.inconsistent += 1;
                }
            } else {
                // t = k / sum, sum = +-2, one multiplication by 1/2
                let t = {
                    let h = (k as u128 * self.inv2 as u128 % r as u128) as u64;
                    if sum > 0 {
                        h
                    } else {
                        negmod(h, r)
                    }
                };
                self.la.mulmods += 1;
                self.la.total += 2;
                match self.fixed[ri] {
                    Some(t0) => {
                        if t0 != t {
                            self.inconsistent += 1;
                        }
                    }
                    None => {
                        self.fixed[ri] = Some(t);
                        self.determined += self.size[ri] as usize;
                    }
                }
            }
        }
    }

    /// Final pass: the value of every determined unknown (one addition each).
    pub fn resolve(&mut self) -> Vec<Option<u64>> {
        let n = self.parent.len();
        let mut out = vec![None; n];
        for v in 0..n {
            let root = self.find(v);
            if let Some(t) = self.fixed[root] {
                let st = if self.s[v] == 1 { t } else { negmod(t, self.r) };
                out[v] = Some(addmod(self.a[v], st, self.r));
                self.la.total += 1;
            }
        }
        out
    }
}

// ── IC: one-time precomputation and per-target descent ──────────────────────

/// How successive relation candidates are produced.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Relgen {
    /// Each candidate is a fresh `[alpha]G` (`T + [beta]G`) from the power table.
    Comb,
    /// After the first, each candidate adds one stored jump `[a_j]G`.
    Walk,
}

/// Result of the one-time IC phase.
pub struct IcPre {
    pub fb: Fb,
    /// `logs[i]`: the projected logarithm of base place `i`, if determined.
    pub logs: Vec<Option<u64>>,
    pub pow: PowTable,
    /// Walk jumps `[a]G + [gamma]H` for the one-time phase (Walk only).
    pub jumps: Vec<(Divisor, u64, u64)>,
    /// G-only jumps for the descent (Walk only).
    pub djumps: Vec<(Divisor, u64)>,
    pub cof: u64,
    pub relgen: Relgen,
    /// Cantor operations of the one-time phase (power table, jumps, relations).
    pub group_ops: u64,
    pub la: LaCount,
    pub trials: u64,
    pub relations: u64,
    pub determined: usize,
    pub inconsistent: u64,
    /// The stop rule was met (otherwise `max_trials` ended the phase).
    pub reached_target: bool,
}

const JUMPS: usize = 16;

/// One-time phase: relations in `G` alone until `q_target` of the base has a
/// determined logarithm (or `max_trials`). `g` must have order `r` (odd prime).
pub fn ic_precompute(
    c: &Genus2Curve,
    g: &Divisor,
    r: u64,
    cof: u64,
    relgen: Relgen,
    q_target: f64,
    max_trials: u64,
    seed: u64,
) -> IcPre {
    use rand::{rngs::StdRng, SeedableRng};
    let k = Fp::new(c.p()).expect("prime field");
    let fb = Fb::new(c);
    let n = fb.len();
    let mut rng = Rng64::new(seed);
    let mut ops = 0u64;
    let pow = PowTable::new(c, g, bits_of(r));
    ops += pow.setup_ops;
    // Relations from G alone live in an r-element subgroup, so at most about
    // r/2 of them are smooth: far fewer than the ~p/2 places when r << p. The
    // relation pool is therefore the whole group, R = [alpha]G + [gamma]H with
    // H = [r]Y of order dividing cof. Projecting by [cof] kills the H term, so
    // log(pi R) = alpha and no target is involved.
    // K = J[cof] can be non-cyclic (measured: a single [r]Y of order 11 in
    // cof = 605; rank up to 4 from rational 2-torsion), so a pool of 48 random
    // elements [r]Y_i of K is built once (counted) and each candidate adds two
    // random pool elements.
    let mut kpool: Vec<Divisor> = vec![];
    if cof > 1 {
        let mut srng = StdRng::seed_from_u64(seed ^ 0x4848);
        while kpool.len() < 48 {
            let y = c.random(&mut srng);
            kpool.push(mul_counted(c, &y, r, &mut ops));
        }
    }
    let draw = |rng: &mut Rng64, ops: &mut u64| -> (Divisor, u64, u64) {
        let alpha = rng.below(r);
        let mut cur = pow.mul(c, alpha, ops);
        if !kpool.is_empty() {
            for _ in 0..2 {
                let k = kpool[rng.below(kpool.len() as u64) as usize];
                cur = cadd(c, &cur, &k, ops);
            }
        }
        (cur, alpha, 0)
    };
    let mut jumps = vec![];
    let mut djumps = vec![];
    if relgen == Relgen::Walk {
        for _ in 0..JUMPS {
            let (d, a, gm) = draw(&mut rng, &mut ops);
            jumps.push((d, a, gm));
        }
        for _ in 0..JUMPS {
            let a = 1 + rng.below(r - 1);
            djumps.push((pow.mul(c, a, &mut ops), a));
        }
    }
    let mut dsu = Dsu::new(n, r);
    for i in 0..n {
        if fb.y0[i] == 0 {
            dsu.fix(i, 0); // 2-torsion place: projected log 0 (r odd)
        }
    }
    let want = (q_target * n as f64).ceil() as usize;
    let mut trials = 0u64;
    let mut relations = 0u64;
    let mut cur = Divisor::IDENTITY;
    let mut alpha = 0u64;
    let mut have_cur = false;
    while dsu.determined < want && trials < max_trials {
        trials += 1;
        match relgen {
            Relgen::Comb => {
                (cur, alpha, _) = draw(&mut rng, &mut ops);
            }
            Relgen::Walk => {
                if !have_cur || cur.is_identity() {
                    (cur, alpha, _) = draw(&mut rng, &mut ops);
                    have_cur = true;
                } else {
                    let (jd, ja, _) = jumps[(rng.next_u64() >> 20) as usize % JUMPS];
                    cur = cadd(c, &cur, &jd, &mut ops);
                    alpha = addmod(alpha, ja, r);
                }
            }
        }
        if let Some([(i, e1), (j, e2)]) = decompose(&k, &fb, &cur) {
            relations += 1;
            dsu.relation(i, e1, j, e2, alpha);
        }
    }
    let determined = dsu.determined;
    let inconsistent = dsu.inconsistent;
    let logs = dsu.resolve();
    IcPre {
        fb,
        logs,
        pow,
        jumps,
        djumps,
        cof,
        relgen,
        group_ops: ops,
        la: dsu.la,
        trials,
        relations,
        determined,
        inconsistent,
        reached_target: determined >= want,
    }
}

/// Outcome of one descent.
#[derive(Clone, Debug)]
pub struct Descent {
    pub x: Option<u64>,
    /// Cantor operations of the descent (the certificate is not included).
    pub group_ops: u64,
    pub trials: u64,
    /// Modular operations of reading off the log.
    pub la_ops: u64,
}

/// Per-target phase: find `beta` with `T + [beta]G` splitting into two places
/// with determined logs, return `x = sum eps_i L_i - beta`.
pub fn ic_descent(
    c: &Genus2Curve,
    pre: &IcPre,
    t: &Divisor,
    r: u64,
    seed: u64,
    max_trials: u64,
) -> Descent {
    let k = Fp::new(c.p()).expect("prime field");
    let mut rng = Rng64::new(seed);
    let mut ops = 0u64;
    let mut trials = 0u64;
    let mut cur = Divisor::IDENTITY;
    let mut beta = 0u64;
    let mut have_cur = false;
    while trials < max_trials {
        trials += 1;
        match pre.relgen {
            Relgen::Comb => {
                beta = rng.below(r);
                cur = pre.pow.add_mul(c, t, beta, &mut ops);
            }
            Relgen::Walk => {
                if !have_cur || cur.is_identity() {
                    beta = rng.below(r);
                    cur = pre.pow.add_mul(c, t, beta, &mut ops);
                    have_cur = true;
                } else {
                    let (jd, ja) = pre.djumps[(rng.next_u64() >> 20) as usize % JUMPS];
                    cur = cadd(c, &cur, &jd, &mut ops);
                    beta = addmod(beta, ja, r);
                }
            }
        }
        if let Some([(i, e1), (j, e2)]) = decompose(&k, &pre.fb, &cur) {
            if let (Some(li), Some(lj)) = (pre.logs[i], pre.logs[j]) {
                let sg = |e: i8, x: u64| if e == 1 { x } else { negmod(x, r) };
                let sum = addmod(sg(e1, li), sg(e2, lj), r);
                let x = submod(sum, beta, r);
                return Descent {
                    x: Some(x),
                    group_ops: ops,
                    trials,
                    la_ops: 3,
                };
            }
        }
    }
    Descent {
        x: None,
        group_ops: ops,
        trials,
        la_ops: 0,
    }
}

// ── Bernstein-Lange precomputed rho ─────────────────────────────────────────

/// Table of distinguished points of walks from known multiples of `G`.
pub struct BlTable {
    pub k: u32,
    mask: u64,
    pub jumps: Vec<(Divisor, u64)>,
    pub pow: PowTable,
    map: HashMap<u64, (Divisor, u64)>,
    /// Cantor operations of the one-time phase (power table, jumps, starts, steps).
    pub group_ops: u64,
    pub entries: usize,
    pub walks: u64,
    pub steps: u64,
    /// The build ended because no new entry appeared for 2000 walks (the actual
    /// cost in `group_ops` can then be below an `Ops` budget).
    pub saturated: bool,
}

/// What ends the table build.
#[derive(Clone, Copy, Debug)]
pub enum BlStop {
    /// Stop once the one-time group operations reach this budget.
    Ops(u64),
    /// Stop once the table holds this many entries (or saturates).
    Entries(usize),
}

fn jump_index(key: u64) -> usize {
    ((mix64(key) >> 24) % JUMPS as u64) as usize
}

/// Build the table with distinguished-point probability `2^-k`.
pub fn bl_precompute(
    c: &Genus2Curve,
    g: &Divisor,
    r: u64,
    k: u32,
    stop: BlStop,
    seed: u64,
) -> BlTable {
    let mut rng = Rng64::new(seed);
    let mut ops = 0u64;
    let pow = PowTable::new(c, g, bits_of(r));
    ops += pow.setup_ops;
    let mut jumps = vec![];
    for _ in 0..JUMPS {
        let a = 1 + rng.below(r - 1);
        jumps.push((pow.mul(c, a, &mut ops), a));
    }
    let mask = if k == 0 { 0 } else { (1u64 << k) - 1 };
    let cap = (1u64 << k) * 20 + 64;
    let mut map: HashMap<u64, (Divisor, u64)> = HashMap::new();
    let (mut walks, mut steps) = (0u64, 0u64);
    let mut stale = 0u64;
    let mut saturated = false;
    let done = |ops: u64, len: usize| match stop {
        BlStop::Ops(b) => ops >= b,
        BlStop::Entries(m) => len >= m,
    };
    'outer: while !done(ops, map.len()) {
        // No new entry for 2000 consecutive walks: the table is saturated (it
        // holds every distinguished point reachable), more budget buys nothing.
        if stale > 2000 {
            saturated = true;
            break;
        }
        walks += 1;
        let mut a = rng.below(r);
        let mut x = pow.mul(c, a, &mut ops);
        let mut since = 0u64;
        loop {
            if x.is_identity() {
                stale += 1;
                break;
            }
            let (jd, ja) = jumps[jump_index(dkey(&x))];
            x = cadd(c, &x, &jd, &mut ops);
            a = addmod(a, ja, r);
            steps += 1;
            since += 1;
            if x.is_identity() {
                stale += 1;
                break;
            }
            if mix64(dkey(&x)) & mask == 0 {
                since = 0;
                match map.entry(dkey(&x)) {
                    std::collections::hash_map::Entry::Occupied(_) => {
                        stale += 1;
                        break; // merged with an earlier walk: restart
                    }
                    std::collections::hash_map::Entry::Vacant(v) => {
                        v.insert((x, a));
                        stale = 0;
                        if done(ops, map.len()) {
                            break 'outer;
                        }
                    }
                }
            } else if since > cap {
                stale += 1;
                break;
            }
            if let BlStop::Ops(b) = stop {
                if ops >= b {
                    break 'outer;
                }
            }
        }
    }
    BlTable {
        k,
        mask,
        jumps,
        pow,
        entries: map.len(),
        map,
        group_ops: ops,
        walks,
        steps,
        saturated,
    }
}

/// Outcome of one online BL solve.
#[derive(Clone, Debug)]
pub struct BlOnline {
    pub x: Option<u64>,
    /// Cantor operations (the certificate is not included).
    pub group_ops: u64,
    pub steps: u64,
    pub restarts: u64,
}

/// Walk from `T + [beta]G` until a distinguished point is in the table (or the
/// walk hits the identity, which also gives the log). `max_ops` ends a hopeless
/// solve (reported as `x = None`).
pub fn bl_online(
    c: &Genus2Curve,
    tab: &BlTable,
    t: &Divisor,
    r: u64,
    seed: u64,
    max_ops: u64,
) -> BlOnline {
    let mut rng = Rng64::new(seed);
    let mut ops = 0u64;
    let (mut steps, mut restarts) = (0u64, 0u64);
    let cap = (1u64 << tab.k) * 20 + 64;
    while ops < max_ops {
        let mut b = rng.below(r);
        let mut x = tab.pow.add_mul(c, t, b, &mut ops);
        let mut since = 0u64;
        loop {
            if x.is_identity() {
                // T + [b]G = O  =>  log T = -b
                return BlOnline {
                    x: Some(negmod(b, r)),
                    group_ops: ops,
                    steps,
                    restarts,
                };
            }
            let (jd, ja) = tab.jumps[jump_index(dkey(&x))];
            x = cadd(c, &x, &jd, &mut ops);
            b = addmod(b, ja, r);
            steps += 1;
            since += 1;
            if x.is_identity() {
                return BlOnline {
                    x: Some(negmod(b, r)),
                    group_ops: ops,
                    steps,
                    restarts,
                };
            }
            if mix64(dkey(&x)) & tab.mask == 0 {
                since = 0;
                if let Some((pt, a2)) = tab.map.get(&dkey(&x)) {
                    if *pt == x {
                        // [x_log + b]G = [a2]G
                        return BlOnline {
                            x: Some(submod(*a2, b, r)),
                            group_ops: ops,
                            steps,
                            restarts,
                        };
                    }
                }
            }
            if since > cap || ops >= max_ops {
                break;
            }
        }
        restarts += 1;
    }
    BlOnline {
        x: None,
        group_ops: ops,
        steps,
        restarts,
    }
}

/// Choose `k` in `0..=bits/2 + 1` by the mean online cost on tuning targets
/// `(T_i)` (not charged to any arm; the caller reports it).
#[allow(clippy::too_many_arguments)]
pub fn bl_best_k(
    c: &Genus2Curve,
    g: &Divisor,
    r: u64,
    stop: BlStop,
    tune: &[Divisor],
    seed: u64,
    max_ops: u64,
) -> (u32, Vec<(u32, f64)>) {
    let mut scores = vec![];
    let mut best = (0u32, f64::INFINITY);
    for k in 0..=(bits_of(r) as u32 / 2 + 1) {
        let tab = bl_precompute(c, g, r, k, stop, seed ^ (0x1000 + k as u64));
        let mut total = 0f64;
        for (i, t) in tune.iter().enumerate() {
            let o = bl_online(c, &tab, t, r, seed ^ (0x77 + i as u64), max_ops);
            total += o.group_ops as f64;
        }
        let mean = total / tune.len().max(1) as f64;
        scores.push((k, mean));
        if mean < best.1 {
            best = (k, mean);
        }
    }
    (best.0, scores)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::cryptanalysis::chained_transfer::measure::jac_instance;

    fn largest_cyclic_prime(mut n: u64) -> u64 {
        let mut best = 1;
        let mut d = 2;
        while d * d <= n {
            if n.is_multiple_of(d) {
                let mut e = 0;
                while n.is_multiple_of(d) {
                    n /= d;
                    e += 1;
                }
                if e == 1 {
                    best = best.max(d);
                }
            }
            d += 1;
        }
        if n > 1 {
            best = best.max(n);
        }
        best
    }

    /// (curve, order, r, generator) for `y² = x⁵ + 3` over small p.
    fn setup(p: u64) -> Option<(Genus2Curve, u64, u64, Divisor)> {
        let c = Genus2Curve::x5_plus_b(p, 3).ok()?;
        let order = c.jacobian_order().ok()?;
        let r = largest_cyclic_prime(order);
        if r < 40 || (order / r).is_multiple_of(r) {
            return None;
        }
        let (g, _) = jac_instance(&c, order, r, 1, p)?;
        Some((c, order, r, g))
    }

    #[test]
    fn fb_logs_are_consistent_with_projected_places() {
        let mut checked = 0;
        for p in [251u64, 1009, 2003] {
            let Some((c, order, r, g)) = setup(p) else {
                continue;
            };
            let cof = order / r;
            for relgen in [Relgen::Comb, Relgen::Walk] {
                let pre = ic_precompute(&c, &g, r, cof, relgen, 0.9, 200 * p, p ^ 5);
                assert!(pre.reached_target, "p={p} {relgen:?}");
                assert_eq!(pre.inconsistent, 0);
                let proj_g = c.mul(&g, cof);
                let mut n = 0;
                for (i, l) in pre.logs.iter().enumerate() {
                    let Some(l) = l else { continue };
                    let place = c.point(pre.fb.xs[i], pre.fb.y0[i]).unwrap();
                    assert_eq!(
                        c.mul(&proj_g, *l),
                        c.mul(&place, cof),
                        "p={p} place {i} log {l}"
                    );
                    n += 1;
                }
                assert!(n as f64 >= 0.9 * pre.fb.len() as f64 - 1.0);
                checked += 1;
            }
        }
        assert!(checked >= 2, "no usable test curve");
    }

    #[test]
    fn descent_recovers_planted_log_and_certifies() {
        let mut checked = 0;
        for p in [251u64, 1009, 2003] {
            let Some((c, o, r, g)) = setup(p) else {
                continue;
            };
            for relgen in [Relgen::Comb, Relgen::Walk] {
                let pre = ic_precompute(&c, &g, r, o / r, relgen, 0.9, 200 * p, p);
                let mut rng = Rng64::new(p + 17);
                for t in 0..20u64 {
                    let x = 1 + rng.below(r - 1);
                    let (tt, _) = (c.mul(&g, x), ());
                    let d = ic_descent(&c, &pre, &tt, r, 1000 + t, 100_000);
                    assert_eq!(d.x, Some(x), "p={p} {relgen:?}");
                    let (ok, ops) = certify_dlog(&c, &g, &tt, d.x.unwrap());
                    assert!(ok && ops > 0);
                    // a wrong answer must fail the certificate
                    assert!(!certify_dlog(&c, &g, &tt, (x + 1) % r).0);
                }
                checked += 1;
            }
        }
        assert!(checked >= 2);
    }

    #[test]
    fn bl_table_hits_and_recovers() {
        let mut checked = 0;
        for p in [251u64, 1009, 2003] {
            let Some((c, _o, r, g)) = setup(p) else {
                continue;
            };
            for k in [0u32, 1, 2] {
                let tab =
                    bl_precompute(&c, &g, r, k, BlStop::Entries(r as usize / 2), p ^ k as u64);
                assert!(tab.entries > 0 && tab.group_ops > 0);
                let mut rng = Rng64::new(p * 3 + k as u64);
                for t in 0..20u64 {
                    let x = 1 + rng.below(r - 1);
                    let tt = c.mul(&g, x);
                    let o = bl_online(&c, &tab, &tt, r, 500 + t, 1_000_000);
                    assert_eq!(o.x, Some(x), "p={p} k={k}");
                    assert!(certify_dlog(&c, &g, &tt, o.x.unwrap()).0);
                }
                checked += 1;
            }
        }
        assert!(checked >= 3);
    }

    #[test]
    fn dsu_solves_a_small_system() {
        // L = [3, 5, 7, 11] mod 101; edges: L0+L1=8, L1-L2=-2, L2+L3=18, L3+L3? use cycle
        let r = 101u64;
        let mut d = Dsu::new(4, r);
        d.relation(0, 1, 1, 1, 8);
        d.relation(1, 1, 2, -1, r - 2);
        d.relation(2, 1, 3, 1, 18);
        assert_eq!(d.determined, 0);
        // cycle 0-3: L0 + L3 = 14 fixes everything: (path sign pattern gives 2*t)
        d.relation(0, 1, 3, 1, 14);
        assert_eq!(d.inconsistent, 0);
        let l = d.resolve();
        // path signs give L0 + L3 = 2 t + 8 = 14, so t = 3 fixes the component
        assert_eq!(d.determined, 4);
        for (v, want) in [3u64, 5, 7, 11].iter().enumerate() {
            assert_eq!(l[v], Some(*want));
        }
    }
}
